<?php require_once 'includes/auth.php';require_once 'includes/db.php';require_login();$rows=db()->query('SELECT c.*,COUNT(r.id) resultados FROM campeonatos c LEFT JOIN resultados r ON r.campeonato_id=c.id AND r.confirmado=1 GROUP BY c.id ORDER BY c.data_inicio DESC')->fetchAll();$pageTitle='Campeonatos';require 'includes/header.php'; ?>
<div class="page-intro"><span class="eyebrow">ISU INTERNATIONAL CALENDAR</span><h1>O circuito <em>mundial.</em></h1><p>Etapas do Grand Prix, Challenger Series e campeonatos internacionais.</p></div><div class="event-cards"><?php foreach($rows as $ev): ?><article class="event-card"><div class="event-card-top"><span class="event-category"><?= e($ev['categoria']) ?></span><span class="status status-<?= strtolower(str_replace(' ','-', $ev['status'])) ?>"><?= e($ev['status']) ?></span></div><div class="event-date-large"><b><?= date('d',strtotime($ev['data_inicio'])) ?>–<?= date('d',strtotime($ev['data_fim'])) ?></b><span><?= strtoupper(date('M Y',strtotime($ev['data_inicio']))) ?></span></div><h3><?= e($ev['nome']) ?></h3><p>⌖ <?= e($ev['cidade']) ?>, <?= e($ev['pais']) ?></p><div class="event-card-bottom"><span><?= (int)$ev['resultados'] ?> resultados confirmados</span><?php if(is_admin()): ?><a href="admin.php#resultados">Gerenciar ↗</a><?php endif; ?></div></article><?php endforeach; ?></div>
